<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Double Pendulum — RK4 + Lagrangian</title>
<style>
  html, body { margin: 0; padding: 0; background: #0d0f14; color: #e6e6e6; font-family: -apple-system, system-ui, sans-serif; }
  #wrap { display: flex; flex-direction: column; align-items: center; padding: 16px; }
  canvas { background: #11141b; border: 1px solid #222633; border-radius: 6px; }
  #ctrl { margin-top: 10px; display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
  button { background: #1b1f29; color: #e6e6e6; border: 1px solid #333a4a; padding: 6px 12px; border-radius: 4px; cursor: pointer; }
  button:hover { background: #252b38; }
  input[type=range] { width: 160px; }
  .lbl { font-size: 12px; opacity: 0.8; }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="c" width="800" height="640"></canvas>
  <div id="ctrl">
    <button id="play">Pause</button>
    <button id="reset">Reset</button>
    <span class="lbl">Trail</span><input id="trail" type="range" min="0" max="3000" value="1200">
    <span class="lbl">Speed</span><input id="speed" type="range" min="1" max="8" value="2" step="1">
    <span class="lbl">θ1</span><input id="a1" type="range" min="-180" max="180" value="120" step="1">
    <span class="lbl">θ2</span><input id="a2" type="range" min="-180" max="180" value="-10" step="1">
  </div>
</div>

<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  // ---- Physical parameters ----
  const g = 9.81;          // gravitational acceleration (m/s^2)
  let L1 = 1.0;            // length rod 1 (m)
  let L2 = 1.0;            // length rod 2 (m)
  let m1 = 1.0;            // mass bob 1 (kg)
  let m2 = 1.0;            // mass bob 2 (kg)

  // pixels per meter for drawing
  const SCALE = Math.min((H - 120) / (L1 + L2 + 0.2), 180);
  const PX_PIVOT_X = W / 2;
  const PX_PIVOT_Y = 90;

  // ---- State: [theta1, omega1, theta2, omega2] ----
  let y = [0, 0, 0, 0];

  function initStateFromUI() {
    const a1 = parseFloat(document.getElementById('a1').value) * Math.PI / 180;
    const a2 = parseFloat(document.getElementById('a2').value) * Math.PI / 180;
    y = [a1, 0, a2, 0];
    trail.length = 0;
  }

  // ---- Lagrangian equations of motion ----
  // Returns derivative dy/dt for state s = [t1,w1,t2,w2]
  function deriv(s) {
    const t1 = s[0], w1 = s[1], t2 = s[2], w2 = s[3];
    const d = t1 - t2;
    const cd = Math.cos(d), sd = Math.sin(d);
    const denom = (2 * m1 + m2 - m2 * Math.cos(2 * d)); // shared denominator factor

    // theta1''
    const a1 = (
      -g * (2 * m1 + m2) * Math.sin(t1)
      - m2 * g * Math.sin(t1 - 2 * t2)
      - 2 * sd * m2 * (w2 * w2 * L2 + w1 * w1 * L1 * cd)
    ) / (L1 * denom);

    // theta2''
    const a2 = (
      2 * sd * (
        w1 * w1 * L1 * (m1 + m2)
        + g * (m1 + m2) * Math.cos(t1)
        + w2 * w2 * L2 * m2 * cd
      )
    ) / (L2 * denom);

    return [w1, a1, w2, a2];
  }

  // ---- RK4 integrator ----
  function rk4Step(s, h) {
    const k1 = deriv(s);
    const s2 = s.map((v, i) => v + 0.5 * h * k1[i]);
    const k2 = deriv(s2);
    const s3 = s.map((v, i) => v + 0.5 * h * k2[i]);
    const k3 = deriv(s3);
    const s4 = s.map((v, i) => v + h * k3[i]);
    const k4 = deriv(s4);
    return s.map((v, i) => v + (h / 6) * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]));
  }

  // ---- Trail ----
  const trail = [];
  let maxTrail = 1200;

  // ---- Simulation timing ----
  let running = true;
  let lastT = performance.now();
  const fixedH = 1 / 480; // physics step (s)
  let accum = 0;
  let speed = 2;

  function bobPositions(state) {
    const x1 = L1 * Math.sin(state[0]);
    const y1 = L1 * Math.cos(state[0]);
    const x2 = x1 + L2 * Math.sin(state[2]);
    const y2 = y1 + L2 * Math.cos(state[2]);
    return { x1, y1, x2, y2 };
  }

  function toPx(x_m, y_m) {
    return [PX_PIVOT_X + x_m * SCALE, PX_PIVOT_Y + y_m * SCALE];
  }

  function draw() {
    ctx.fillStyle = '#11141b';
    ctx.fillRect(0, 0, W, H);

    // subtle grid
    ctx.strokeStyle = '#161a24';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 40) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
    }
    for (let j = 0; j < H; j += 40) {
      ctx.beginPath(); ctx.moveTo(0, j); ctx.lineTo(W, j); ctx.stroke();
    }

    // pivot
    ctx.fillStyle = '#3a4152';
    ctx.beginPath();
    ctx.arc(PX_PIVOT_X, PX_PIVOT_Y, 5, 0, Math.PI * 2);
    ctx.fill();

    // trail
    if (trail.length > 1) {
      for (let i = 1; i < trail.length; i++) {
        const a = i / trail.length;
        // color gradient: blue -> magenta -> orange
        const hue = (200 + 200 * (i / trail.length)) % 360;
        ctx.strokeStyle = `hsla(${hue}, 80%, 60%, ${a * 0.85})`;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(trail[i - 1].px, trail[i - 1].py);
        ctx.lineTo(trail[i].px, trail[i].py);
        ctx.stroke();
      }
    }

    const p = bobPositions(y);
    const [bx1, by1] = toPx(p.x1, p.y1);
    const [bx2, by2] = toPx(p.x2, p.y2);

    // rods
    ctx.strokeStyle = '#cfd3dc';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(PX_PIVOT_X, PX_PIVOT_Y);
    ctx.lineTo(bx1, by1);
    ctx.lineTo(bx2, by2);
    ctx.stroke();

    // bobs
    ctx.fillStyle = '#ffcf57';
    ctx.beginPath();
    ctx.arc(bx1, by1, 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#ff5d5d';
    ctx.beginPath();
    ctx.arc(bx2, by2, 9, 0, Math.PI * 2);
    ctx.fill();

    // HUD
    ctx.fillStyle = '#9aa0ad';
    ctx.font = '12px monospace';
    ctx.fillText(`θ1 = ${(y[0] * 180 / Math.PI).toFixed(1)}°  ω1 = ${y[1].toFixed(2)}`, 12, 20);
    ctx.fillText(`θ2 = ${(y[2] * 180 / Math.PI).toFixed(1)}°  ω2 = ${y[3].toFixed(2)}`, 12, 38);
    ctx.fillText(`L1=${L1} m  L2=${L2} m  m1=${m1} kg  m2=${m2} kg  g=${g}`, 12, 56);
    ctx.fillText(`RK4  h=${fixedH.toFixed(4)}s  steps/frame=${speed}`, 12, 74);
  }

  function loop(now) {
    let dt = (now - lastT) / 1000;
    lastT = now;
    if (dt > 0.1) dt = 0.1; // clamp

    if (running) {
      accum += dt;
      // fixed-step physics, scaled by "speed"
      const stepsThisFrame = speed;
      for (let i = 0; i < stepsThisFrame; i++) {
        y = rk4Step(y, fixedH);
        // record trail point (in pixel coords)
        const p = bobPositions(y);
        const [bx2, by2] = toPx(p.x2, p.y2);
        trail.push({ px: bx2, py: by2 });
        while (trail.length > maxTrail) trail.shift();
      }
    }

    draw();
    requestAnimationFrame(loop);
  }

  // ---- UI wiring ----
  document.getElementById('play').addEventListener('click', e => {
    running = !running;
    e.target.textContent = running ? 'Pause' : 'Play';
    lastT = performance.now();
  });
  document.getElementById('reset').addEventListener('click', () => {
    initStateFromUI();
  });
  document.getElementById('trail').addEventListener('input', e => {
    maxTrail = parseInt(e.target.value);
    while (trail.length > maxTrail) trail.shift();
  });
  document.getElementById('speed').addEventListener('input', e => {
    speed = parseInt(e.target.value);
  });
  document.getElementById('a1').addEventListener('input', () => { initStateFromUI(); });
  document.getElementById('a2').addEventListener('input', () => { initStateFromUI(); });

  // init
  maxTrail = parseInt(document.getElementById('trail').value);
  speed = parseInt(document.getElementById('speed').value);
  initStateFromUI();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

Implementation notes:

- **Lagrangian equations**: The standard closed-form equations for a double pendulum are implemented directly in `deriv()`. Both angular accelerations share the denominator `(2m1 + m2 − m2·cos(2θ1−2θ2))`, which is numerically stable for the configurations exercised here.
- **RK4**: `rk4Step()` performs a single 4th-order Runge–Kutta step with a fixed time step `h = 1/480 s`. Each animation frame runs `speed` physics steps (default 2), giving an effective simulation rate of 2× realtime while preserving integration accuracy.
- **Trail**: The second bob's pixel position is appended every physics step into a circular buffer. Trail segments are stroked with an HSL gradient and alpha falloff so the oldest points fade out.
- **Controls**: Pause/Play, Reset, trail length, simulation speed, and initial angles θ1/θ2 (in degrees, converted to radians). Adjusting an angle slider resets the state to that configuration with zero initial angular velocity.
- **Rendering**: A light grid is drawn for reference; the pivot, rods, and bobs are rendered each frame on top of the trail.
